INSERT INTO postings (id, organization_id, title, field, programs, positions, requirements, start_date, end_date, apply_deadline, status, created_at) VALUES (1, 1, 'Веб хөгжүүлэгч дадлагжигч', 'Программ хангамж', '["Программ хангамж","Мэдээллийн технологи"]', 5, 'HTML, CSS, JavaScript-ийн суурь мэдлэгтэй байх. Багийн хөгжүүлэлтэд оролцож, код шалгалт (code review) хийлгэнэ. Git ашиглаж чаддаг байх давуу тал.', '2026-11-09', '2026-12-04', '2026-12-03', 'open', '2026-10-12T09:00:00Z');
INSERT INTO postings (id, organization_id, title, field, programs, positions, requirements, start_date, end_date, apply_deadline, status, created_at) VALUES (2, 2, 'Өгөгдлийн шинжилгээний туслах', 'Өгөгдлийн шинжилгээ', '["Мэдээллийн систем","Компьютерийн ухаан"]', 2, 'SQL, Python-ийн суурь мэдлэг. Тайлан, хяналтын самбарын өгөгдлийг бэлтгэх ажилд оролцоно.', '2026-11-09', '2026-12-04', '2026-12-03', 'open', '2026-10-12T09:00:00Z');
INSERT INTO postings (id, organization_id, title, field, programs, positions, requirements, start_date, end_date, apply_deadline, status, created_at) VALUES (3, 3, 'Сүлжээ, системийн администраторын туслах', 'Сүлжээ, дэд бүтэц', '["Мэдээллийн технологи"]', 2, 'Сүлжээний үндсэн ойлголт, Linux-ийн тушаалын мөр. Серверийн хяналт, нөөцлөлтөд тусална.', '2026-11-09', '2026-12-04', '2026-12-03', 'open', '2026-10-12T09:00:00Z');
INSERT INTO postings (id, organization_id, title, field, programs, positions, requirements, start_date, end_date, apply_deadline, status, created_at) VALUES (4, 4, 'Мобайл апп хөгжүүлэгч', 'Мобайл хөгжүүлэлт', '["Программ хангамж"]', 2, 'Flutter эсвэл React Native-ийн анхан шатны туршлага. Бодит төслийн дэлгэц, API холболтыг хөгжүүлнэ.', '2026-11-09', '2026-12-04', '2026-12-03', 'open', '2026-10-12T09:00:00Z');
INSERT INTO postings (id, organization_id, title, field, programs, positions, requirements, start_date, end_date, apply_deadline, status, created_at) VALUES (5, 5, 'Чанарын баталгаа, туршилтын инженер', 'Программ хангамжийн туршилт', '[]', 4, 'Туршилтын сценари бичих, гар болон автомат туршилт хийх. Алдааг бүртгэж, засвар хийсэн эсэхийг шалгана.', '2026-11-09', '2026-12-04', '2026-12-03', 'open', '2026-10-12T09:00:00Z');
INSERT INTO postings (id, organization_id, title, field, programs, positions, requirements, start_date, end_date, apply_deadline, status, created_at) VALUES (6, 6, 'ERP системийн дэмжлэг', 'Санхүү, ERP', '["Мэдээллийн систем"]', 2, 'Бизнесийн үйл явцыг ойлгох, баримтжуулах. Хэрэглэгчийн лавлагаа, тохиргооны ажилд оролцоно.', '2026-11-09', '2026-12-04', '2026-12-03', 'open', '2026-10-12T09:00:00Z');
