INSERT INTO postings (id, organization_id, title, field, programs, positions, requirements, start_date, end_date, apply_deadline, status, created_at) VALUES (8, 8, 'Мэдээллийн аюулгүй байдлын дадлага', 'Кибер аюулгүй байдал', '["Мэдээллийн технологи","Компьютерийн ухаан"]', 2, 'Сүлжээ, вэб аюулгүй байдлын үндсэн ойлголт. Эмзэг байдлын шалгалтын тайлан бэлтгэхэд туслана.', '2026-11-09', '2026-12-04', '2026-12-03', 'open', '2026-10-12T09:00:00Z');
INSERT INTO postings (id, organization_id, title, field, programs, positions, requirements, start_date, end_date, apply_deadline, status, created_at) VALUES (9, 1, 'Backend хөгжүүлэгч (Node.js)', 'Программ хангамж', '["Программ хангамж","Мэдээллийн технологи"]', 4, 'JavaScript, REST API, өгөгдлийн сангийн суурь мэдлэг. Дотоод системийн API хөгжүүлэхэд оролцоно.', '2026-11-09', '2026-12-04', '2026-12-03', 'open', '2026-10-12T09:00:00Z');
