INSERT INTO announcements (semester_id, author_id, title, body, file_id, created_at) VALUES (2, 19, 'Тайлан илгээх хугацааны сануулга', 'Дадлагын тайлан 2026.11.27-ны өдрийн 18:00 цагаас өмнө системд ирсэн байх ёстой. Хугацаа хэтэрсэн тайланг систем хүлээн авахгүй тул файлуудаа урьдчилан бэлтгээрэй.', NULL, '2026-11-16T08:30:00Z');
